FUNCTION @@proc@@ (p_id IN NUMBER) RETURN VARCHAR2 IS
    l_label VARCHAR2(30);
BEGIN
    SELECT /* FROM DUAL */ CASE WHEN @@col@@ > 0 THEN 'POS' ELSE 'FROM DUAL' END -- @expect
      INTO l_label
      FROM @@tab@@
     WHERE id = p_id;
    RETURN l_label;
END @@proc@@;

PROCEDURE @@proc@@ (p_ids IN SYS.ODCINUMBERLIST) IS
    l_val NUMBER;
BEGIN
    FOR i IN 1 .. p_ids.COUNT LOOP
        BEGIN
            @@proc2@@(p_ids(i));
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NULL;
        END;
        SELECT @@col@@ -- @expect
          INTO l_val
          FROM @@tab@@
         WHERE id = p_ids(i);
        l_val := 100 / l_val;
    END LOOP;
EXCEPTION
    WHEN ZERO_DIVIDE THEN
        l_val := 0;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_name VARCHAR2(100);

    FUNCTION lookup (p_key IN NUMBER) RETURN VARCHAR2 IS
        l_v VARCHAR2(100);
    BEGIN
        SELECT @@col@@ INTO l_v FROM @@tab@@ WHERE id = p_key; -- @expect
        RETURN l_v;
    END lookup;
BEGIN
    l_name := lookup(p_id);
    @@proc2@@(l_name);
END @@proc@@;

FUNCTION @@proc@@ (p_dept IN NUMBER) RETURN NUMBER IS
    l_max NUMBER;
BEGIN
    -- one group at most, yet the rule still applies
    SELECT MAX(@@col@@) -- @expect
      INTO l_max
      FROM @@tab@@
     WHERE dept_id = p_dept
     GROUP BY dept_id;
    RETURN l_max;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_v NUMBER;
BEGIN
    $IF $$use_cache $THEN
        l_v := 0;
    $ELSE
        SELECT @@col@@ INTO l_v FROM @@tab@@ WHERE id = p_id; -- @expect
    $END
    @@proc2@@(l_v);
END @@proc@@;

