PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_v NUMBER;
BEGIN
    <<lvl1>>
    BEGIN
        <<lvl2>>
        BEGIN
            <<lvl3>>
            DECLARE
                l_w NUMBER;
            BEGIN
                SELECT @@col@@ INTO l_w FROM @@tab@@ WHERE id = p_id;
                l_v := l_w;
            END lvl3;
        EXCEPTION
            WHEN ZERO_DIVIDE THEN
                l_v := 0;
        END lvl2;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            l_v := -1;
    END lvl1;
    @@proc2@@(l_v);
END @@proc@@;

PROCEDURE @@proc@@ (p_dept IN NUMBER, p_cnt OUT NUMBER, p_hi OUT NUMBER) IS
    l_now DATE;
BEGIN
    SELECT COUNT(*), -- how many
           MAX(@@col@@) -- highest
      INTO p_cnt, p_hi
      FROM @@tab@@
     WHERE dept_id = p_dept;
    SELECT SYSDATE
      INTO l_now
      FROM
           DUAL;
    @@proc2@@(l_now);
END @@proc@@;

PROCEDURE @@proc@@ (p_run IN NUMBER) IS
    l_text VARCHAR2(200) := q'[SELECT x INTO y FROM z WHERE 1 = 0]';
    l_ids  SYS.ODCINUMBERLIST;
BEGIN
    -- SELECT id INTO l_x FROM @@tab@@;
    SELECT id
      BULK COLLECT INTO l_ids
      FROM @@tab@@
     WHERE run_id = p_run;
    INSERT INTO @@tab2@@ (id)
    SELECT id FROM @@tab@@ WHERE run_id = p_run;
    @@proc2@@(l_text);
END @@proc@@;

FUNCTION @@proc@@ (p_code IN VARCHAR2) RETURN NUMBER IS
    l_id NUMBER;

    PROCEDURE noop IS
    BEGIN
        NULL;
    END noop;
BEGIN
    noop;
    SELECT id
      INTO l_id
      FROM @@tab@@
     WHERE code = p_code;
    RETURN l_id;
EXCEPTION
    WHEN ZERO_DIVIDE
      OR TOO_MANY_ROWS THEN
        RETURN NULL;
END @@proc@@;

FUNCTION @@proc@@ (p_ids IN SYS.ODCINUMBERLIST) RETURN NUMBER IS
    l_sum NUMBER := 0;
    l_v   NUMBER;
BEGIN
    FOR i IN 1 .. p_ids.COUNT LOOP
        CASE
            WHEN p_ids(i) > 0 THEN
                SELECT @@col@@ INTO l_v FROM @@tab@@ WHERE id = p_ids(i);
                l_sum := l_sum + l_v;
            ELSE
                NULL;
        END CASE;
    END LOOP;
    RETURN l_sum;
EXCEPTION
    WHEN OTHERS THEN
        RAISE;
END @@proc@@;
